def solve(n, b):
    a = []
    for i in range(n):
        if b[i] % n == 0:
            a.append(b[i] // n)
        else:
            return "NO"
    return "YES\n" + " ".join(map(str, a))

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        b = list(map(int, input().split()))
        results.append(solve(n, b))
    print("\n".join(results))

if __name__ == "__main__":
    main()
